const items = $input.all();
const keywords = items.map(item => item.json.keyword_phrase);
const queries = [];

const platformTarget = [
  { platform: 'linkedin', prefix: 'site:linkedin.com/posts' },
  { platform: 'threads', prefix: 'site:threads.net' },
  { platform: 'facebook', prefix: 'site:facebook.com' }
];

for (const target of platformTarget) {
  for (const kw of keywords) {
    queries.push(`"${kw}" ${target.prefix}`);
  }
}

return [{
  json: {
    platform: 'multi_platform',
    keywords: keywords,
    queries: queries.slice(0, 10),
    max_results: 10
  }
}];

const response = $input.first()?.json || {};
const candidates = response.candidates || [];

return candidates.map(c => ({
  json: {
    platform: c.platform,
    post_url: c.post_url,
    author_name: c.author_name,
    author_url: c.author_url,
    post_text: c.post_text,
    posted_at: c.posted_at,
    matched_keywords: c.matched_keywords,
    source_query: c.source_query,
    post_text_hash: c.post_text_hash
  }
}));

const candidates = $('Flatten Candidate Leads').all();
const existingDbRows = $input.all();

const existingUrls = new Set(existingDbRows.map(row => row.json.post_url));
const existingHashes = new Set(existingDbRows.map(row => row.json.post_text_hash));
const newItems = [];

for (const candidate of candidates) {
  const url = candidate.json.post_url;
  const hash = candidate.json.post_text_hash;
  if (url && !existingUrls.has(url) && !existingHashes.has(hash)) {
    newItems.push(candidate);
  }
}

return newItems;

