const items = $input.all();
const processed = [];
const filteredCandidates = $('Filter Out Existing Duplicates').all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const candidate = filteredCandidates[i]?.json || {};

  let aiRes = {};
  try {
    let rawText = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    rawText = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
    aiRes = JSON.parse(rawText);
  } catch (err) {
    aiRes = {
      is_lead: false,
      is_potential_client: false,
      is_project_or_agency_need: false,
      intent: 'IRRELEVANT',
      reason: 'JSON parse error from Gemini AI: ' + err.message
    };
  }

  processed.push({
    json: {
      ...candidate,
      ai_result: aiRes
    }
  });
}

return processed;

const items = $input.all();
const scoredLeads = [];

for (const item of items) {
  const data = item.json;
  const ai = data.ai_result || {};

  let score = 0;

  if (ai.is_potential_client && ai.is_project_or_agency_need) {
    if (['DIRECT_REQUEST', 'HIRING_AGENCY', 'OUTSOURCING'].includes(ai.intent)) score += 30;
    else if (ai.intent === 'RECOMMENDATION_REQUEST') score += 20;
    else if (ai.intent === 'BUSINESS_PROBLEM') score += 15;

    if (ai.problem && ai.problem.length > 10) score += 15;
    if (ai.urgency === 'HIGH') score += 15;
    if (ai.budget_signal) score += 10;
    if (ai.company_name || ['SMB', 'MID_MARKET', 'ENTERPRISE'].includes(ai.business_type)) score += 10;
  }

  if (ai.intent === 'HIRING_EMPLOYEE') score -= 50;
  if (ai.intent === 'SELLING_SERVICE') score -= 50;
  if (['GENERAL_DISCUSSION', 'EDUCATIONAL'].includes(ai.intent)) score -= 30;
  if (ai.intent === 'IRRELEVANT' || !ai.is_lead) score -= 50;

  score = Math.max(0, Math.min(100, score));

  let temp = 'IRRELEVANT';
  if (score >= 80) temp = 'HOT';
  else if (score >= 50) temp = 'WARM';
  else if (score >= 20) temp = 'COLD';

  const safeString = (val) => val ? String(val).replace(/'/g, "''") : null;

  scoredLeads.push({
    json: {
      platform: data.platform || 'web',
      post_url: data.post_url,
      author_name: safeString(data.author_name || ai.company_name),
      author_url: safeString(data.author_url),
      post_text: safeString(data.post_text),
      posted_at: data.posted_at || new Date().toISOString(),
      matched_keywords: JSON.stringify(data.matched_keywords || []),
      service_needed: safeString(ai.service_needed),
      intent: ai.intent || 'IRRELEVANT',
      lead_score: score,
      lead_temperature: temp,
      urgency: ai.urgency || 'UNKNOWN',
      budget_signal: safeString(ai.budget_signal),
      business_type: ai.business_type || 'UNKNOWN',
      qualification_reason: safeString(ai.reason),
      suggested_outreach_angle: safeString(ai.problem ? `Help solve ${ai.problem}` : 'Propose tech partnership'),
      status: 'NEW',
      post_text_hash: data.post_text_hash,
      is_qualified: ['HOT', 'WARM', 'COLD'].includes(temp)
    }
  });
}

return scoredLeads;
